const embeddings = $input.all();
const cases = $("Prepare Evaluation Cases1").all();

if (embeddings.length !== cases.length) {
  throw new Error(
    `Embedding/case count mismatch: ${embeddings.length} responses for ${cases.length} cases`,
  );
}

return embeddings.map((item, index) => {
  const source = cases[index].json;
  const embedding = item.json.data?.[0]?.embedding;

  if (!Array.isArray(embedding) || embedding.length !== 1024) {
    throw new Error(
      `Embedding missing or not 1024 dimensions for item ${index + 1}`,
    );
  }

  return {
    json: {
      ...source,
      dense_vector: embedding,
    },
  };
});

